import React, { useMemo } from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, random } from '../remotionShim';
{/* Start Google Fonts Loader */}
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;700;900`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */}



export type BeingGurkhaProps = Record<string, any>;

// Helper to split text for animation
const splitTextToChars = (text: string) => {
  const chars: { char: string; id: string; isSpace: boolean }[] = [];
  let counter = 0;
  // Preserve spaces as individual characters for fixed-width layouts
  text.split("").forEach((char, i) => {
    chars.push({ char, id: `char-${i}-${counter}`, isSpace: char === " " });
    counter++;
  });
  return chars;
};

const FlipRow: React.FC<{
  text: string;
  fontSize: number;
  letterSpacing: number;
  textColor: string;
  frame: number;
  stylizedA: boolean;
  rowId: string;
  delayOffset?: number;
}> = ({ text, fontSize, letterSpacing, textColor, frame, stylizedA, rowId, delayOffset = 0 }) => {
  
  const characters = useMemo(() => splitTextToChars(text), [text]);
  const flipChars = "ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";

  return (
    <div
      style={{
        display: "flex",
        flexDirection: "row",
        flexWrap: "nowrap", // Prevent wrapping for rows
        justifyContent: "center",
        alignItems: "center",
        gap: `${letterSpacing}px`,
      }}
    >
      {characters.map((item, index) => {
        // Flicker Logic
        const stagger = 3; 
        const flickerDuration = 20; 
        const startFrame = delayOffset + (index * stagger);
        const endFrame = startFrame + flickerDuration;
        
        let displayChar = item.char;
        let isVisible = true;
        let isFlickering = false;

        if (frame < startFrame) {
           displayChar = ""; 
           // In reference, empty slots are black/dark
        } else if (frame < endFrame) {
          isFlickering = true;
          const seed = Math.floor(random(index * 1234 + rowId.length + Math.floor(frame / 2)) * flipChars.length);
          displayChar = flipChars[seed];
        }

        const isA = displayChar?.toUpperCase() === "A" && stylizedA;
        const flapSize = fontSize * 1.4; // Taller flap
        const flapWidth = fontSize * 1.0; // Slightly narrower than height

        return (
          <div
            key={item.id}
            style={{
              width: flapWidth,
              height: flapSize,
              backgroundColor: "#111", // Dark flap background
              color: textColor,
              fontSize: fontSize,
              borderRadius: fontSize * 0.08,
              position: "relative",
              display: "flex",
              justifyContent: "center",
              alignItems: "center",
              boxShadow: "0px 2px 4px rgba(0,0,0,0.8)",
              overflow: "hidden",
              border: '1px solid #222'
            }}
          >
            {/* Top Gloss */}
            <div
              style={{
                position: "absolute",
                top: 0,
                left: 0,
                right: 0,
                height: "50%",
                background: "linear-gradient(to bottom, rgba(255,255,255,0.1), rgba(255,255,255,0.02))",
                borderBottom: "2px solid rgba(0,0,0,1)", 
                zIndex: 1,
              }}
            />
            
            <span style={{ position: "relative", zIndex: 0, lineHeight: 0, fontFamily: "Oswald, sans-serif", fontWeight: 700 }}>
              {displayChar}
            </span>

            {/* Hinge Line */}
            <div
              style={{
                position: "absolute",
                top: "50%",
                left: 0,
                right: 0,
                height: Math.max(1, fontSize * 0.02),
                backgroundColor: "#000",
                transform: "translateY(-50%)",
                zIndex: 2,
                boxShadow: "0px 1px 0px rgba(255,255,255,0.05)",
              }}
            />

            {/* Stylized A Mask */}
            {isA && (
              <div
                style={{
                  position: "absolute",
                  top: "60%", 
                  left: "25%",
                  width: "50%",
                  height: "8%",
                  backgroundColor: "#111", 
                  zIndex: 3,
                }}
              />
            )}
            
            {/* Mechanical Holes on side (visual detail from ref) */}
             <div style={{ position: 'absolute', top: '45%', left: 2, width: 2, height: 4, background: '#333', borderRadius: '50%' }} />
             <div style={{ position: 'absolute', top: '45%', right: 2, width: 2, height: 4, background: '#333', borderRadius: '50%' }} />

          </div>
        );
      })}
    </div>
  );
};

